#include <bits/stdc++.h>
using namespace std;

bool matchesPattern(const string& pattern, int number) {
    int lastDigit = -1;
    int len = pattern.length();
    for (int i = len - 1; i >= 0; i--) {
        int digitInNumber = number % 10;
        char c = pattern[i];
        if (c == 'X') {
            if (lastDigit >= 0 && lastDigit != digitInNumber) {
                return false;
            }
            lastDigit = digitInNumber;
        } else if (c != '_') {
            if ((c - '0') != digitInNumber) {
                return false;
            }
        }
        if (len > 1 && i == 0 && digitInNumber == 0) {
            return false;
        }
        number /= 10;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string patternStr;
    getline(cin, patternStr);
    int maxVal = 1;
    for (size_t i = 0; i < patternStr.length(); i++) {
        maxVal *= 10;
    }
    int countMatches = 0;
    for (int candidate = 0; candidate < maxVal; candidate += 25) {
        if (matchesPattern(patternStr, candidate)) {
            countMatches++;
        }
    }
    cout << countMatches << "\n";
    return 0;
}

